head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > titleAuto]<br/>Body 영역의 각 Cell 에 Header 값 조합으로 title 속성을 자동 생성할지 설정합니다.",
    "validation" : [
        "accessibility=true 이면 titleAuto 속성이 true 로 강제 설정됩니다.",
        "titleFormatter 속성이 설정되면 titleAuto 속성은 무시됩니다.",
        "true 설정 시 Body 영역의 각 Cell 에 title 속성을 자동 생성하며, 각 Cell 의 inputType 에 따라 다음 형식대로 설정됩니다. text: Header 값(embeddedInput=true 이면 'Header Cell'), anchor·button·link·secret: Header 값, autoComplete: 값이 있으면 'Header Label(또는 Cell)' 없으면 'Header 오토컴플릿', calendar: 값이 있으면 'Header Cell' 없으면 'Header 캘린더', checkbox·radio: 선택이면 'Header 선택' 해제면 'Header 선택 안함', select: 값이 있으면 'Header Cell' 없으면 'Header 셀렉트'.",
        "false(기본값) 설정 시 Body 영역의 각 Cell 에 title 속성을 생성하지 않습니다.",
        "SubTotal Row 에는 적용되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 값 읽기 (미설정이면 속성 미부여 = 기본값)
    let titleAutoVal = con_titleAuto.getValue();
    let accessibilityVal = con_accessibility.getValue();
    let titleFormatterVal = con_titleFormatter.getValue();

    // 동작 조건/현재 설정 라벨 생성
    $c.gcm.createLabel('label="컬럼 inputType 혼합: col1=text / col2=text(embeddedInput=true) / col3=secret / col4=anchor / col5=autoComplete(embeddedInput) / col6=calendar(embeddedInput) / col7=checkbox / col8=select(embeddedInput). dept 컬럼 기준 SubTotal(소계) Row 포함."', '', 'label1');
    $c.gcm.createLabel('label="현재 설정: titleAuto=' + (titleAutoVal === '' ? '미설정(기본 false)' : titleAutoVal) + ' / accessibility=' + (accessibilityVal === '' ? '미설정(기본 false)' : accessibilityVal) + ' / titleFormatter=' + (titleFormatterVal === '' ? '미설정' : '설정') + '"', '', 'label2');

    // dataList 직접 생성 (그룹 기준 dept 가 연속되도록 정렬, 빈 행 0)
    // - col4(autoComplete)/col6(calendar)/col8(select) 은 '값 있음' 행과 '값 없음' 행을 모두 포함하여 형식 분기 검증
    // - col7(checkbox) 은 선택(1) / 해제(0) 행을 모두 포함
    let strNameSpace = $c.gcm.getNameSpace();
    let strDl = '';
    strDl += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDl += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDl += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDl += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDl += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDl += '<w2:column id="col5" name="col5" dataType="text"></w2:column>';
    strDl += '<w2:column id="col6" name="col6" dataType="text"></w2:column>';
    strDl += '<w2:column id="col7" name="col7" dataType="text"></w2:column>';
    strDl += '<w2:column id="col8" name="col8" dataType="text"></w2:column>';
    strDl += '<w2:column id="amount" name="amount" dataType="number"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true">';
    // dept(소계 그룹) / col1 text / col2 text(embedded) / col3 secret / col4 anchor
    // col5 autoComplete(Y/N value) / col6 calendar(date) / col7 checkbox(1/0) / col8 select(Y/N value)
    // [dept, col1, col2, col3, col4, col5(auto), col6(cal), col7(chk), col8(sel), amount]
    let rows = [
        ['Sales', 'Apple',  'Embed1', '1234', 'Link1', 'Y', '20251101', '1', 'Y', 100],
        ['Sales', 'Banana', 'Embed2', '5678', 'Link2', '',  '',         '0', '',  200],
        ['Dev',   'Cherry', 'Embed3', '9012', 'Link3', 'N', '20251103', '1', 'N', 300],
        ['Dev',   'Date',   'Embed4', '3456', 'Link4', '',  '',         '0', '',  400]
    ];
    for (let r = 0; r < rows.length; r++) {
        strDl += '<w2:row>';
        strDl += '<dept><![CDATA[' + rows[r][0] + ']]></dept>';
        strDl += '<col1><![CDATA[' + rows[r][1] + ']]></col1>';
        strDl += '<col2><![CDATA[' + rows[r][2] + ']]></col2>';
        strDl += '<col3><![CDATA[' + rows[r][3] + ']]></col3>';
        strDl += '<col4><![CDATA[' + rows[r][4] + ']]></col4>';
        strDl += '<col5><![CDATA[' + rows[r][5] + ']]></col5>';
        strDl += '<col6><![CDATA[' + rows[r][6] + ']]></col6>';
        strDl += '<col7><![CDATA[' + rows[r][7] + ']]></col7>';
        strDl += '<col8><![CDATA[' + rows[r][8] + ']]></col8>';
        strDl += '<amount><![CDATA[' + rows[r][9] + ']]></amount>';
        strDl += '</w2:row>';
    }
    strDl += '</w2:data>';
    strDl += '</w2:dataList>';
    $p.data.create(strDl);

    // titleAuto / accessibility / titleFormatter 속성 (미설정 시 속성 미부여 = 기본값)
    let titleAutoAttr = titleAutoVal === '' ? '' : 'titleAuto="' + titleAutoVal + '" ';
    let accessibilityAttr = accessibilityVal === '' ? '' : 'accessibility="' + accessibilityVal + '" ';
    // titleFormatter 설정 시: 임의 함수(scwin.myTitleFormatter)를 부여하여 titleAuto 자동 형식 대신 이 결과가 적용됨을 확인
    let titleFormatterAttr = titleFormatterVal === '' ? '' : 'titleFormatter="scwin.myTitleFormatter" ';

    // target 생성 (Header inputType=text + Body inputType 혼합 + SubTotal Row)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + titleAutoAttr + accessibilityAttr + titleFormatterAttr + 'checkAllType="false" dataList="data:dlt_bind" id="" style="width:900px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="titleAuto 테스트 그리드"></w2:caption>';
    // Header : 모든 컬럼 inputType=text (titleAuto 는 헤더 inputType=text 인 경우 동작)
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="90"  inputType="text" id="hdept" value="부서"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="hcol1" value="텍스트"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="hcol2" value="임베디드"></w2:column>';
    strTarget += '<w2:column width="90"  inputType="text" id="hcol3" value="시크릿"></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" id="hcol4" value="앵커"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="hcol5" value="오토컴플릿"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="hcol6" value="캘린더"></w2:column>';
    strTarget += '<w2:column width="80"  inputType="text" id="hcol7" value="체크박스"></w2:column>';
    strTarget += '<w2:column width="*"   inputType="text" id="hcol8" value="셀렉트"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    // Body : inputType 혼합
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="90"  inputType="text"   dataType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text"   dataType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text"   dataType="text" embeddedInput="true" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="90"  inputType="secret" dataType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="100" inputType="anchor" dataType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '<w2:column width="110" inputType="autoComplete" dataType="text" embeddedInput="true" id="col5" dataList="col5">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:item><w2:label>예</w2:label><w2:value>Y</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>아니오</w2:label><w2:value>N</w2:value></w2:item>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:column>';
    strTarget += '<w2:column width="110" inputType="calendar" dataType="date" embeddedInput="true" viewType="icon" displayMode="label" calendarFormat="yyyyMMdd" displayFormat="yyyy-MM-dd" id="col6" dataList="col6"></w2:column>';
    strTarget += '<w2:column width="80"  inputType="checkbox" dataType="text" trueValue="1" falseValue="0" id="col7" dataList="col7"></w2:column>';
    strTarget += '<w2:column width="*"   inputType="select" dataType="text" embeddedInput="true" id="col8" dataList="col8">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:item><w2:label>예</w2:label><w2:value>Y</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>아니오</w2:label><w2:value>N</w2:value></w2:item>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    // SubTotal : dept 기준 소계 Row (titleAuto 가 적용되지 않아야 함 = V5)
    strTarget += '<w2:subTotal style="" id="subTotal1" targetColumnID="dept">';
    strTarget += '<w2:row style="" id="srow1">';
    strTarget += '<w2:column width="90"  inputType="text" id="sdept" value="소계"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="scol1" value=""></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="scol2" value=""></w2:column>';
    strTarget += '<w2:column width="90"  inputType="text" id="scol3" value=""></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" id="scol4" value=""></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="scol5" value=""></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="scol6" value=""></w2:column>';
    strTarget += '<w2:column width="80"  inputType="text" id="scol7" value=""></w2:column>';
    strTarget += '<w2:column width="*"   inputType="expression" dataType="number" displayFormat="#,###" id="scol8" expression="sum(\'amount\')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:subTotal>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 생성 직후 각 Body Cell 의 title 속성을 읽어 inputType별 가이드 형식과 비교 출력 (검증 자동 출력)
    scwin.printTitleResult();
}



// titleFormatter 함수 (con_titleFormatter=설정 시에만 부여) — titleAuto 자동 형식 대신 이 결과가 적용됨을 확인
scwin.myTitleFormatter = function (rowIndex, colIndex, data) {
    return 'FMT(' + rowIndex + ',' + colIndex + ')';
};



// 각 Body Cell 의 td title 속성을 읽어 결과창에 출력
scwin.printTitleResult = function () {
    let gridId = scwin.target1.id;
    let titleAutoVal = con_titleAuto.getValue();
    let accessibilityVal = con_accessibility.getValue();
    let titleFormatterVal = con_titleFormatter.getValue();

    wf_body_bottom.getObj("scwin").setReturnValue("[설정] titleAuto=" + (titleAutoVal === '' ? '미설정' : titleAutoVal) + " / accessibility=" + (accessibilityVal === '' ? '미설정' : accessibilityVal) + " / titleFormatter=" + (titleFormatterVal === '' ? '미설정' : '설정'));

    // 컬럼 라벨/대상 (col1~col8 + dept). embedded/anchor/autoComplete/select 은 td 내부 input/a 에 title 이 부여될 수 있어 td 와 내부 요소 모두 확인
    let cols = [
        { col: 'col1', label: 'text' },
        { col: 'col2', label: 'text(embeddedInput)' },
        { col: 'col3', label: 'secret' },
        { col: 'col4', label: 'anchor' },
        { col: 'col5', label: 'autoComplete' },
        { col: 'col6', label: 'calendar' },
        { col: 'col7', label: 'checkbox' },
        { col: 'col8', label: 'select' }
    ];

    // Body 데이터 Row 0(값 있음) / Row 1(값 없음·해제) 두 행의 title 을 출력 (값 유무 분기 검증)
    for (let r = 0; r < 2; r++) {
        for (let i = 0; i < cols.length; i++) {
            let colIdx = scwin.target1.getColumnIndex(cols[i].col);
            let td = document.querySelector("td[id*='" + gridId + "_cell_" + r + "_" + colIdx + "']");
            let titleVal = '';
            if (td) {
                // td 자체 title 우선, 없으면 내부 input/a 의 title
                titleVal = td.getAttribute('title');
                if (titleVal === null || titleVal === '') {
                    // embedded/anchor/autoComplete/select 은 td 내부 요소(input/a/select 등)에 title 부여
                    let inner = td.querySelector('input, a, [title]');
                    if (inner) {
                        titleVal = inner.getAttribute('title') || '';
                    }
                }
                if (titleVal === null) titleVal = '';
            }
            wf_body_bottom.getObj("scwin").setReturnValue("[Row" + r + " " + cols[i].label + "] title='" + titleVal + "'");
        }
    }

    // SubTotal Row 의 셀 title 확인 (V5: 미생성). SubTotal Row 는 subTotal 정의 row id(srow1) 로 렌더됨
    let subTr = document.querySelector("tr[id='srow1']") || document.querySelector("tr[id$='srow1']");
    let subTitleInfo = '(SubTotal Row 미검출)';
    if (subTr) {
        let subTds = subTr.querySelectorAll('td');
        let titled = 0;
        for (let s = 0; s < subTds.length; s++) {
            let tv = subTds[s].getAttribute('title');
            if (tv !== null && tv !== '') titled++;
        }
        subTitleInfo = 'title 가 부여된 셀 수=' + titled + ' / 전체 셀 수=' + subTds.length;
    }
    wf_body_bottom.getObj("scwin").setReturnValue("[SubTotal Row] " + subTitleInfo + " (V5: 0 = title 미생성 기대)");
};
